{
  "id": "6c0e24ec-c7bc-4454-94e3-a66a53d337a2",
  "version": "1.8",
  "name": "ExpenseApproval",
  "variables": {
    "globals": [],
    "nodes": []
  },
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Expense Report Submitted"
      },
      "inputs": {
        "entryPointId": "66acaa70-dc82-423d-8d26-4cd340c372f2",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "managerApproval",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Manager Approval"
      },
      "inputs": {
        "title": "Expense Report Approval",
        "priority": "Medium",
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        },
        "schema": {
          "schemaId": "a1b2c3d4-e5f6-7890-abcd-ef1234567890",
          "fields": [
            {
              "id": "submitterid",
              "label": "Submitted By",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.submitterId"
            },
            {
              "id": "amount",
              "label": "Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.start.output.amount"
            },
            {
              "id": "description",
              "label": "Description",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.description"
            },
            {
              "id": "category",
              "label": "Category",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.category"
            },
            {
              "id": "comments",
              "label": "Manager Comments",
              "type": "text",
              "direction": "output",
              "variable": "vars.managerComments"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "End"
            }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "comments": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkDecision",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.managerApproval.status === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "logApproved",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Approval"
      },
      "inputs": {
        "script": "const submitterId = $vars.start.output.submitterId || 'Unknown';\nconst amount = $vars.start.output.amount || 0;\nconst description = $vars.start.output.description || '';\nconst category = $vars.start.output.category || '';\nconst comments = $vars.managerApproval.output.comments || '';\nreturn {\n  action: 'APPROVED',\n  submitterId: submitterId,\n  amount: amount,\n  description: description,\n  category: category,\n  managerComments: comments,\n  logMessage: 'Expense approved for ' + submitterId + ' | Amount: ' + amount + ' | Category: ' + category\n};"
      }
    },
    {
      "id": "logRejected",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Rejection"
      },
      "inputs": {
        "script": "const submitterId = $vars.start.output.submitterId || 'Unknown';\nconst amount = $vars.start.output.amount || 0;\nconst description = $vars.start.output.description || '';\nconst category = $vars.start.output.category || '';\nconst comments = $vars.managerApproval.output.comments || '';\nreturn {\n  action: 'REJECTED',\n  submitterId: submitterId,\n  amount: amount,\n  description: description,\n  category: category,\n  managerComments: comments,\n  logMessage: 'Expense rejected for ' + submitterId + ' | Amount: ' + amount + ' | Category: ' + category\n};"
      }
    },
    {
      "id": "endApproved",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End — Approved"
      }
    },
    {
      "id": "endRejected",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "End — Rejected"
      }
    }
  ],
  "edges": [
    {
      "id": "e-start-hitl",
      "sourceNodeId": "start",
      "sourceHandle": "output",
      "targetNodeId": "managerApproval",
      "targetPort": "input"
    },
    {
      "id": "e-hitl-decision",
      "sourceNodeId": "managerApproval",
      "sourceHandle": "completed",
      "targetNodeId": "checkDecision",
      "targetPort": "input"
    },
    {
      "id": "e-decision-approved",
      "sourceNodeId": "checkDecision",
      "sourceHandle": "true",
      "targetNodeId": "logApproved",
      "targetPort": "input"
    },
    {
      "id": "e-decision-rejected",
      "sourceNodeId": "checkDecision",
      "sourceHandle": "false",
      "targetNodeId": "logRejected",
      "targetPort": "input"
    },
    {
      "id": "e-approved-end",
      "sourceNodeId": "logApproved",
      "sourceHandle": "success",
      "targetNodeId": "endApproved",
      "targetPort": "input"
    },
    {
      "id": "e-rejected-end",
